    x=s['models'][model];cmp=x['comparisons'][criterion];c[cmp if cmp in c else 'UNKNOWN']+=1;c['predicted_UNKNOWN']+=int(x['predicted'][criterion] not in ['FAILURE','SUCCESS']);c['observed_FAILURE']+=int(x['observed'][criterion]=='FAILURE');c['observed_SUCCESS']+=int(x['observed'][criterion]=='SUCCESS');c['complete_observation']+=int(x['observation_complete']);c['complete_prediction']+=int(x['prediction_complete'])
